class Solution {
public:
    string decodeString(string s) {
        string res;
        vector<pair<int, int>> st;
        int num = 0;
        for (char c : s) {
            if (isdigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '[') {
                st.push_back({(int)res.length(), num});
                num = 0;
            } else if (c == ']') {
                auto [start, k] = st.back();
                st.pop_back();
                int len = (int)res.length() - start;
                for (int i = 1; i < k; ++i) {
                    for (int j = 0; j < len; ++j) {
                        char ch = res[start + j];
                        res.push_back(ch);
                    }
                }
            } else {
                res.push_back(c);
            }
        }
        return res;
    }
};
